const r = $json || {};
const d = $('Extrair Decisão').first().json;
const reservado = r.decisao_reservada === true || String(r.decisao_reservada).toLowerCase() === 'true';
const expirado = r.fiscal_token_expirado === true || String(r.fiscal_token_expirado).toLowerCase() === 'true';
const oracleGuardOk = r.oracle_guard_ok === true || String(r.oracle_guard_ok).toLowerCase() === 'true';
let acao = 'INVALIDO';
let evento_fiscal = 'TOKEN_INVALIDO';
let msg = '';
if (!r.id) { msg = 'Chamado nao encontrado.'; }
else if (d.oraculo===true && !oracleGuardOk) { evento_fiscal = 'ORACULO_BLOQUEADO_DB'; msg = 'Confirmacao automatica sem reserva ou contexto experimental valido.'; }
else if (reservado && d.decisao === 'confirmar') { acao = 'CONFIRMAR'; evento_fiscal = 'DECISAO_CONFIRMAR'; msg = 'Duplicidade confirmada #' + r.id; }
else if (reservado && d.decisao === 'nao_duplicado') { acao = 'REJEITAR'; evento_fiscal = 'DECISAO_REJEITAR'; msg = 'Duplicidade rejeitada #' + r.id; }
else if (!reservado && r.decisao_fiscal) { acao = 'JA_REGISTRADO'; evento_fiscal = 'CLIQUE_DUPLO'; msg = 'Decisao ja registrada ou em processamento para o chamado #' + r.id + ': ' + r.decisao_fiscal + '.'; }
else if (!reservado && expirado) { evento_fiscal = 'TOKEN_EXPIRADO'; msg = 'Token fiscal expirado para o chamado #' + r.id + '. Gere nova triagem ou revise manualmente no GLPI.'; }
else if (!reservado && r.em_aprovacao_fiscal) { msg = 'Token fiscal invalido ou ja utilizado para o chamado #' + r.id + '.'; }
else if (!r.em_aprovacao_fiscal) { msg = 'Chamado nao aguarda decisao fiscal.'; }
else { msg = 'Decisao invalida.'; }
console.log('[WF04][LOG] Validacao fiscal acao=' + acao + ' reservado=' + reservado + ' expirado=' + expirado);
return [{json:{...r,acao,evento_fiscal,msg,fiscal_token_expirado:expirado,origem_decisao:d.origem_decisao||'FISCAL_GLPI'}}];

const r = $('PG: Limpar Duplicidade').first().json;
const origem = $('Validar Fiscal').first().json || {};
const token = String(origem.fiscal_decision_token || '').trim();
const marker = token ? `[WF02_DUPLICIDADE:${origem.id || r.id}:${token}]` : '';
const baseUrl = String((typeof process !== 'undefined' && process.env.GLPI_API_URL) || 'http://host.docker.internal:9080/apirest.php').replace(/\/$/, '');
const appToken = String((typeof process !== 'undefined' && process.env.GLPI_APP_TOKEN) || 'SeedToken2024CampusRP');
const sessionToken = String($('GLPI: Sessão Fiscal').first().json.session_token || '');
const headers = {'App-Token': appToken, 'Session-Token': sessionToken, 'Content-Type': 'application/json'};
let removidos = 0;
let falhas = 0;
try {
  const followups = await helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/Ticket/' + Number(r.id) + '/ITILFollowup',
    headers,
    json: true
  });
  const candidatos = [];
  for (const f of Array.isArray(followups) ? followups : []) {
    const fid = Number(f.id || f['2']);
    const content = String(f.content || f['content'] || '');
    const criadoPelaTriagem = marker && content.includes(marker);
    if (!fid || !criadoPelaTriagem) continue;
    candidatos.push(fid);
  }
  const resultados = await Promise.all(candidatos.map(async (fid) => {
    try {
      await helpers.httpRequest({
        method: 'DELETE',
        url: baseUrl + '/ITILFollowup/' + fid,
        headers,
        json: true
      });
      return {fid, ok:true};
    } catch (e) {
      console.log('[WF04][LOG] Falha ao remover followup #' + fid + ' do chamado #' + r.id + ': ' + e.message);
      return {fid, ok:false};
    }
  }));
  removidos = resultados.filter(x => x.ok).length;
  falhas = resultados.length - removidos;
} catch (e) {
  console.log('[WF04][LOG] Falha ao remover followups de duplicidade #' + r.id + ': ' + e.message);
}
console.log('[WF04][LOG] Followups de duplicidade removidos #' + r.id + ': ' + removidos + ' | falhas=' + falhas + ' | marker=' + (marker ? 'ok' : 'ausente'));
return [{json:{...r,followups_removidos:removidos,followups_remocao_falhas:falhas,marcador_followup:marker}}];

